<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Clerk'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}
$route=filter_var($_POST['route_id']??null,FILTER_VALIDATE_INT);$date=trim((string)($_POST['travel_date']??''));$trip=(string)($_POST['trip']??'');$entries=is_array($_POST['learners']??null)?$_POST['learners']:[];$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date);$e=DateTimeImmutable::getLastErrors();$valid=$d!==false&&$d->format('Y-m-d')===$date&&($e===false||(!$e['warning_count']&&!$e['error_count']));if(!$route||!$valid||$date>date('Y-m-d')||!in_array($trip,['Outbound','Return'],true)){$_SESSION['error']='Choose a valid transport route, trip and date no later than today.';header('Location: ../?page=transport');exit;}$allowed=['Boarded','Not On Bus','Authorized Alternative'];$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT r.id FROM transport_routes r JOIN transport_vehicles v ON v.id=r.vehicle_id AND v.status='Active' WHERE r.id=:id AND r.active=1 FOR UPDATE");$q->execute(['id'=>$route]);if(!$q->fetch())throw new DomainException('Transport register requires an active route and vehicle.');$check=$pdo->prepare("SELECT id FROM transport_assignments WHERE student_id=:student AND route_id=:route AND status='Active' AND starts_on<=:date_start AND (ends_on IS NULL OR ends_on>=:date_end) LIMIT 1");$save=$pdo->prepare('INSERT INTO transport_register(student_id,route_id,travel_date,trip,status,note,recorded_by) VALUES(:student,:route,:date,:trip,:status,:note,:user) ON DUPLICATE KEY UPDATE route_id=VALUES(route_id),status=VALUES(status),note=VALUES(note),recorded_by=VALUES(recorded_by),recorded_at=CURRENT_TIMESTAMP');$saved=0;foreach($entries as $studentId=>$row){$studentId=filter_var((string)$studentId,FILTER_VALIDATE_INT);if(!$studentId||!is_array($row))throw new DomainException('A transport register row is invalid.');$status=(string)($row['status']??'');if($status==='')continue;if(!in_array($status,$allowed,true))throw new DomainException('Choose a valid bus register status.');$note=trim((string)($row['note']??''));if(strlen($note)>255)throw new DomainException('Register notes must be 255 characters or fewer.');$check->execute(['student'=>$studentId,'route'=>$route,'date_start'=>$date,'date_end'=>$date]);if(!$check->fetch())throw new DomainException('A learner is not assigned to this route on the selected date.');$save->execute(['student'=>$studentId,'route'=>$route,'date'=>$date,'trip'=>$trip,'status'=>$status,'note'=>$note?:null,'user'=>$user['id']]);$saved++;}if(!$saved)throw new DomainException('Record a status for at least one learner.');audit_log('transport.register_saved','transport_register',null,['route_id'=>$route,'date'=>$date,'trip'=>$trip,'learner_count'=>$saved]);$pdo->commit();$_SESSION['notice']='Transport register saved for '.$saved.' learner(s).';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Transport register save failed: '.$e->getMessage());$_SESSION['error']='Could not save the transport register.';}header('Location: ../?page=transport&route_id='.(int)$route.'&date='.rawurlencode($date).'&trip='.rawurlencode($trip));exit;
